  const s1='1 · Actual and potential growth',s2='2 · Positive and negative output gaps',s3='3 · Fiscal expansion and the multiplier',s4='4 · Independent assessment';
  const slides=[];
  const add=(id,kind,title,section,body={})=>{const refs=body.sourceRefs||['text','model'];slides.push({id,kind,title,section,...body,sourceRefs:refs,sources:refs.map(k=>`${sources[k].type}: ${sources[k].ref} ${sources[k].detail}`)});};
  const diag=(id,title,section,notes)=>add(id,'diagram',title,section,{label:'DIAGRAM · 图解',diagram:id,notes});
